+        closureBindingRecords: readonly PagClosureBindingRecord[],
+        closureValueBindingRecords: readonly PagClosureValueBindingRecord[],
+        fieldAccessRecords: readonly RealizedPagFieldAccessRecord[],
+        methodContextRecords: readonly PagMethodContextRecord[],
+        semanticValueFlowRecords: readonly PagSemanticValueFlowRecord[],
+        pointsTo: DiffPTData<NodeID, NodeID, IPtsCollection<NodeID>>,
+    ) {
+        this.dvfg = new DVFG(callGraph);
+        const pointerContextRefs = new Map<Context, AnalyzerContextRef>();
+        const containerContextRefs = new Map<PagNode, AnalyzerContextRef>();
+        const independentContextRefs = new Map<PagNode, AnalyzerContextRef>();
+        for (const context of contextCache.getContextList()) {
+            const reference: AnalyzerContextRef = Object.freeze({
+                kind: 'pointer-analysis',
+                context,
+            });
+            pointerContextRefs.set(context, reference);
+            this.contextRefs.add(reference);
+        }
+        const pagCopyEdges: PagEdge[] = [];
+        for (const candidate of this.pag.getNodesIter()) {
+            if (!(candidate instanceof PagNode)) {
+                throw new Error('PAG contains a non-PagNode object');
+            }
+            const context = this.contextRefFor(
+                candidate,
+                contextCache,
+                pointerContextRefs,
+                containerContextRefs,
+                independentContextRefs,
+            );
+            const location: AnalyzerPagLocationRef = Object.freeze({
+                kind: 'pag',
+                node: candidate,
+                context,
+            });
+            this.pagLocations.set(candidate, location);
+            this.contextRefs.add(context);
+            for (const edge of candidate.getOutgoingCopyEdges() ?? []) {
+                if (!(edge instanceof PagEdge)
+                    || edge.getSrcNode() !== candidate
+                    || !(edge.getDstNode() instanceof PagNode)
+                    || !this.ownsPagEdge(edge)) {
+                    throw new Error('PAG Copy inventory contains an invalid edge');
+                }
+                if (edge.getKind() === PagEdgeKind.InterProceduralCopy) continue;
+                if (edge.getKind() !== PagEdgeKind.Copy) {
+                    throw new Error('PAG Copy inventory contains a non-Copy edge');
+                }
