+        this.allHeapStorageFacts = this.publishHeapStorageFacts();
+        this.publishCallBindings(callBindingRecords, contextCache, pointerContextRefs);
+        this.allCallBindings = Object.freeze([...this.callBindingFacts]);
+        this.publishCallableTargets(callableTargetRecords, pointsTo);
+        this.allCallableTargets = Object.freeze([...this.callableTargetFacts]);
+        this.publishValueFlows(
+            methodContextRecords,
+            callBindingRecords,
+            semanticValueFlowRecords,
+            contextCache,
+            pointerContextRefs,
+        );
+        this.allValueFlows = Object.freeze([...this.valueFlowFacts]);
+        this.publishMethodBoundaryFacts(methodContextRecords, contextCache, pointerContextRefs);
+        this.allMethodBoundaryFacts = Object.freeze([...this.methodBoundaryFactSet]);
+        this.publishClosureBindings(
+            closureBindingRecords,
+            closureValueBindingRecords,
+            contextCache,
+            pointerContextRefs,
+        );
+        this.allClosureBindings = Object.freeze([...this.closureBindingFacts]);
+        this.publishFieldAccesses(
+            fieldAccessRecords,
+            pointsTo,
+            contextCache,
+            pointerContextRefs,
+        );
+        this.allFieldAccesses = Object.freeze([...this.fieldAccessFacts]);
+        this.publishControlFlows();
+        Object.freeze(this);
