+
+    parameterLocations(
+        binding: CallBindingFact,
+        parameterIndex: number,
+    ): readonly AnalyzerLocationRef[] {
+        if (!this.ownsCallBinding(binding)) {
+            throw new Error('call binding is not owned by this snapshot');
+        }
+        if (!Number.isInteger(parameterIndex) || parameterIndex < 0) {
+            return Object.freeze([]);
+        }
+        const boundTargets = binding.argumentBindings
+            .filter(candidate => candidate.parameterIndex === parameterIndex)
+            .map(candidate => candidate.target)
+            .filter(location => location.context === binding.calleeContext);
+        if (boundTargets.length > 0) {
+            return Object.freeze([...new Set(boundTargets)]);
+        }
+        const physicalParameterIndex = binding.callsite.semanticCallable === undefined
+            ? parameterIndex
+            : binding.callee.getExplicitParameterPhysicalIndex(parameterIndex);
+        if (physicalParameterIndex === undefined) return Object.freeze([]);
+        const parameter = binding.callee.getParameterInstances()[physicalParameterIndex];
+        if (!(parameter instanceof Local)) return Object.freeze([]);
+        const declaration = parameter.getDeclaringStmt();
+        if (!declaration) return Object.freeze([]);
+        const locations = this.locationsAt(declaration, parameter, 'definition')
+            .filter(location => location.context === binding.calleeContext);
+        return Object.freeze([...new Set(locations)]);
