+        const locations: AnalyzerPagLocationRef[] = [];
+        const nodes = this.pag.getNodesByValue(value);
+        if (!nodes) return Object.freeze(locations);
+        for (const nodeId of [...nodes.values()].sort((left, right) => left - right)) {
+            const node = this.pag.getNode(nodeId);
+            if (!(node instanceof PagNode)) {
+                throw new Error(`PAG location ${nodeId} is not a PagNode`);
+            }
+            const location = this.locationOfPagNode(node);
