+
+    pointsToLocationsOf(
+        location: AnalyzerPagLocationRef,
+    ): readonly AnalyzerPagLocationRef[] {
+        if (!this.ownsLocation(location)) {
+            throw new Error('PAG location is not owned by this snapshot');
+        }
+        return this.pointsToLocations.get(location) ?? Object.freeze([]);
