+
+    heapCarrierFacts(): readonly AnalyzerHeapCarrierFact[] {
+        return this.allHeapCarrierFacts;
+    }
+
+    heapCarriersOf(
+        location: AnalyzerPagLocationRef,
+    ): readonly AnalyzerHeapCarrierFact[] {
+        if (!this.ownsLocation(location)) {
+            throw new Error('PAG location is not owned by this snapshot');
+        }
