+
+    ownsHeapCarrierFact(fact: AnalyzerHeapCarrierFact): boolean {
+        return this.heapCarrierFactSet.has(fact);
+    }
+
+    heapStorageFacts(): readonly AnalyzerHeapStorageFact[] {
+        return this.allHeapStorageFacts;
+    }
+
+    heapStoragesOf(
+        owner: AnalyzerPagLocationRef,
+    ): readonly AnalyzerHeapStorageFact[] {
+        if (!this.ownsLocation(owner)) {
+            throw new Error('PAG location is not owned by this snapshot');
+        }
+        return this.heapStorageFactsByOwner.get(owner) ?? Object.freeze([]);
+    }
+
+    ownsHeapStorageFact(fact: AnalyzerHeapStorageFact): boolean {
+        return this.heapStorageFactSet.has(fact);
+    }
+
+    heapContainmentsFrom(
+        carrier: AnalyzerPagLocationRef,
+    ): readonly AnalyzerHeapContainmentFact[] {
+        if (!this.ownsLocation(carrier)) {
+            throw new Error('PAG location is not owned by this snapshot');
+        }
+        const cached = this.heapContainmentsByRoot.get(carrier);
+        if (cached) return cached;
