+        const containments: AnalyzerHeapContainmentFact[] = [];
+        const visitedOwners = new Set<AnalyzerPagLocationRef>([carrier]);
+        const visitedStorages = new Set<AnalyzerPagLocationRef>();
+        const queue: Array<Readonly<{
+            owner: AnalyzerPagLocationRef;
+            proof: readonly AnalyzerHeapContainmentStep[];
+        }>> = [{ owner: carrier, proof: Object.freeze([]) }];
