+        for (let index = 0; index < queue.length; index++) {
+            const current = queue[index];
+            for (const storageFact of this.heapStoragesOf(current.owner)) {
+                const storageProof = Object.freeze([
+                    ...current.proof,
+                    storageFact,
+                ]);
+                if (!visitedStorages.has(storageFact.storageLocation)) {
+                    visitedStorages.add(storageFact.storageLocation);
+                    const fact: AnalyzerHeapContainmentFact = Object.freeze({
+                        kind: 'heap-containment',
+                        rootCarrierLocation: carrier,
+                        containedStorageLocation: storageFact.storageLocation,
+                        proof: storageProof,
+                    });
+                    this.heapContainmentFactSet.add(fact);
+                    containments.push(fact);
+                }
+                for (const carrierFact of this.heapCarriersOf(storageFact.storageLocation)) {
+                    if (visitedOwners.has(carrierFact.carrierLocation)) continue;
+                    visitedOwners.add(carrierFact.carrierLocation);
+                    queue.push(Object.freeze({
+                        owner: carrierFact.carrierLocation,
+                        proof: Object.freeze([
+                            ...storageProof,
+                            carrierFact,
+                        ]),
