+        const frozen = Object.freeze(containments);
+        this.heapContainmentsByRoot.set(carrier, frozen);
+        return frozen;
+    }
+
+    ownsHeapContainmentFact(fact: AnalyzerHeapContainmentFact): boolean {
+        return this.heapContainmentFactSet.has(fact);
+    }
+
+    locationsAt(
+        statement: Stmt,
+        value: Value,
+        role: "definition" | "use",
+    ): readonly AnalyzerLocationRef[] {
+        if (!this.program.ownsStatement(statement)) {
+            throw new Error('statement is not owned by this snapshot');
+        }
+        const valueFlowLocations: AnalyzerLocationRef[] = [];
+        for (const node of this.dvfg.getValueNodes(value)) {
+            if (node.getStmt() !== statement || node.getRole() !== role) continue;
+            for (const location of this.valueFlowLocations.get(node)?.values() ?? []) {
+                valueFlowLocations.push(location);
+            }
+        }
+        if (valueFlowLocations.length > 0) {
+            return Object.freeze(valueFlowLocations);
+        }
+
+        const pagLocations: AnalyzerLocationRef[] = [];
+        const nodes = this.pag.getNodesByValue(value);
+        if (nodes) {
+            for (const nodeId of [...nodes.values()].sort((left, right) => left - right)) {
+                const node = this.pag.getNode(nodeId);
+                if (!(node instanceof PagNode)) {
+                    throw new Error(`PAG location ${nodeId} is not a PagNode`);
+                }
+                pagLocations.push(this.locationOfPagNode(node));
+            }
+        }
+        return Object.freeze(pagLocations);
+    }
+
+    locationOfPagNode(node: PagNode): AnalyzerPagLocationRef {
+        const location = this.pagLocations.get(node);
+        if (!location) {
+            throw new Error('PAG node is not owned by this snapshot');
+        }
