+
+    owns(fact: AnalyzerOwnedFact): boolean {
+        if (this.ownsHeapCarrierFact(fact as AnalyzerHeapCarrierFact)) return true;
+        if (this.ownsHeapStorageFact(fact as AnalyzerHeapStorageFact)) return true;
+        if (this.ownsHeapContainmentFact(fact as AnalyzerHeapContainmentFact)) return true;
+        if (fact instanceof PagNode) return this.ownsPagNode(fact);
+        if (fact instanceof PagEdge) return this.ownsPagEdge(fact);
+        if (fact instanceof DVFGNode) return this.ownsDvfgNode(fact);
+        if (fact instanceof DVFGEdge) return this.ownsDvfgEdge(fact);
+        if (fact instanceof CallGraphNode) return this.ownsCallGraphNode(fact);
+        if (fact instanceof CallGraphEdge) return this.ownsCallGraphEdge(fact);
+        if (fact instanceof ArkMethod) return this.program.ownsMethod(fact);
+        if (fact instanceof Stmt) return this.program.ownsStatement(fact);
+        if (fact instanceof AbstractInvokeExpr) return this.program.ownsInvokeExpr(fact);
+        return false;
+    }
