+    private publishHeapCarrierFacts(): readonly AnalyzerHeapCarrierFact[] {
+        const facts: AnalyzerHeapCarrierFact[] = [];
+        const locations = [...this.pagLocations.values()]
+            .sort((left, right) => left.node.getID() - right.node.getID());
+        for (const endpointLocation of locations) {
+            const carrierLocations = new Set<AnalyzerPagLocationRef>(
+                this.pointsToLocations.get(endpointLocation) ?? [],
+            );
+            if (this.isHeapCarrierNode(endpointLocation.node)) {
+                carrierLocations.add(endpointLocation);
+            }
+            const endpointFacts = [...carrierLocations]
+                .sort((left, right) => left.node.getID() - right.node.getID())
+                .map(carrierLocation => {
+                    const fact: AnalyzerHeapCarrierFact = Object.freeze({
+                        kind: 'heap-carrier',
+                        endpointLocation,
+                        carrierLocation,
+                    });
+                    this.heapCarrierFactSet.add(fact);
+                    facts.push(fact);
+                    return fact;
+                });
+            this.heapCarrierFactsByEndpoint.set(
+                endpointLocation,
+                Object.freeze(endpointFacts),
+            );
+        }
+        return Object.freeze(facts);
+    }
+
+    private publishHeapStorageFacts(): readonly AnalyzerHeapStorageFact[] {
+        const facts: AnalyzerHeapStorageFact[] = [];
+        const storageNodes = [...this.pagLocations.keys()]
+            .filter((node): node is PagInstanceFieldNode =>
+                node instanceof PagInstanceFieldNode
+                && Number.isInteger(node.getBasePt())
+                && this.pag.hasNode(node.getBasePt()))
+            .sort((left, right) => left.getID() - right.getID());
+        const mutableByOwner = new Map<
+            AnalyzerPagLocationRef,
+            AnalyzerHeapStorageFact[]
+        >();
+        for (const storageNode of storageNodes) {
+            const ownerNode = this.pag.getNode(storageNode.getBasePt());
+            if (!(ownerNode instanceof PagNode)) {
+                throw new Error('heap storage owner is not a PagNode');
+            }
+            const fact: AnalyzerHeapStorageFact = Object.freeze({
+                kind: 'heap-storage',
+                ownerLocation: this.locationOfPagNode(ownerNode),
+                storageLocation: this.locationOfPagNode(storageNode),
+            });
+            const ownerFacts = mutableByOwner.get(fact.ownerLocation) ?? [];
+            ownerFacts.push(fact);
+            mutableByOwner.set(fact.ownerLocation, ownerFacts);
+            this.heapStorageFactSet.add(fact);
+            facts.push(fact);
+        }
+        for (const [owner, ownerFacts] of mutableByOwner) {
+            this.heapStorageFactsByOwner.set(owner, Object.freeze(ownerFacts));
+        }
+        return Object.freeze(facts);
+    }
+
+    private isHeapCarrierNode(node: PagNode): boolean {
+        return node instanceof PagNewExprNode
+            || node instanceof PagNewContainerExprNode
+            || node instanceof PagFuncNode
+            || node instanceof PagGlobalThisNode;
+    }
+
+    private ownsPagNode(node: PagNode): boolean {
+        return this.pag.hasNode(node.getID()) && this.pag.getNode(node.getID()) === node;
+    }
+
+    private ownsPagEdge(edge: PagEdge): boolean {
+        const source = edge.getSrcNode();
+        const target = edge.getDstNode();
+        return source instanceof PagNode
+            && target instanceof PagNode
+            && this.ownsPagNode(source)
+            && this.ownsPagNode(target)
+            && source.getOutgoingEdges().has(edge);
+    }
+
+    private ownsCallGraphNode(node: CallGraphNode): boolean {
+        return this.callGraph.hasNode(node.getID())
+            && this.callGraph.getNode(node.getID()) === node;
+    }
+
+    private ownsCallGraphEdge(edge: CallGraphEdge): boolean {
+        const source = edge.getSrcNode();
+        const target = edge.getDstNode();
+        return source instanceof CallGraphNode
+            && target instanceof CallGraphNode
+            && this.ownsCallGraphNode(source)
+            && this.ownsCallGraphNode(target)
+            && source.getOutgoingEdges().has(edge);
+    }
+
+    private ownsDvfgNode(node: DVFGNode): boolean {
+        return this.dvfg.hasNode(node.getID())
+            && this.dvfg.getNode(node.getID()) === node;
+    }
+
+    private ownsDvfgEdge(edge: DVFGEdge): boolean {
+        const source = edge.getSrcNode();
+        const target = edge.getDstNode();
+        return source instanceof DVFGNode
+            && target instanceof DVFGNode
+            && this.ownsDvfgNode(source)
+            && this.ownsDvfgNode(target)
+            && source.getOutgoingEdges().has(edge);
+    }
+
+    private publishControlFlows(): void {
+        for (const method of this.program.methods()) {
+            const cfg = method.getCfg();
+            if (!cfg) continue;
+            const facts = new AnalyzerControlFlowFacts(method, cfg);
+            this.controlFlowsByMethod.set(method, facts);
+            this.controlFlowFacts.add(facts);
+        }
+    }
+
+    private contextRefFor(
+        node: PagNode,
+        contextCache: ContextCache,
+        pointerContextRefs: Map<Context, AnalyzerContextRef>,
+        containerContextRefs: Map<PagNode, AnalyzerContextRef>,
+        independentContextRefs: Map<PagNode, AnalyzerContextRef>,
+    ): AnalyzerContextRef {
+        if (node.getCid() === CONTAINER_ELEMENT_CID) {
+            const ownerId = node.getBasePt();
+            const owner = this.pag.hasNode(ownerId)
+                ? this.pag.getNode(ownerId)
+                : undefined;
+            if (!(owner instanceof PagNode)) {
+                throw new Error('container element location has no exact PAG owner');
+            }
+            const existing = containerContextRefs.get(owner);
+            if (existing) return existing;
+            const created: AnalyzerContextRef = Object.freeze({
+                kind: 'container-element',
+                owner,
+            });
+            containerContextRefs.set(owner, created);
+            return created;
+        }
+        if (node.getCid() === emptyID) {
+            const existing = independentContextRefs.get(node);
+            if (existing) return existing;
+            const created: AnalyzerContextRef = Object.freeze({
+                kind: 'context-independent',
+                owner: node,
+            });
+            independentContextRefs.set(node, created);
+            return created;
+        }
+
+        const context = contextCache.getContext(node.getCid());
+        if (!context) {
+            throw new Error(
+                `PAG node context is not owned by this PointerAnalysis: node=${node.getID()} cid=${node.getCid()}`,
+            );
+        }
+        const existing = pointerContextRefs.get(context);
+        if (existing) return existing;
+        const created: AnalyzerContextRef = Object.freeze({
+            kind: 'pointer-analysis',
+            context,
+        });
+        pointerContextRefs.set(context, created);
+        return created;
+    }
+
+    private publishCallBindings(
+        records: readonly PagCallBindingRecord[],
+        contextCache: ContextCache,
+        pointerContextRefs: Map<Context, AnalyzerContextRef>,
+    ): void {
+        for (const record of records) {
+            if (!this.program.ownsMethod(record.caller)
+                || !this.program.ownsMethod(record.callee)
+                || !this.program.ownsStatement(record.callsite.callStmt)) {
+                throw new Error('call binding references a program object outside this snapshot');
+            }
+            const invokeExpr = record.callsite.callStmt.getInvokeExpr();
+            const occurrence: AnalyzerInvocationSiteRef | undefined = invokeExpr
+                ? this.program.callsites(record.caller).find(candidate =>
+                    candidate.statement === record.callsite.callStmt
+                    && candidate.invokeExpr === invokeExpr,
+                )
+                : this.program.fieldSites(record.caller).find(candidate =>
+                    candidate.statement === record.callsite.callStmt,
+                );
+            if (!occurrence) {
+                throw new Error('call binding has no exact program-model invocation site');
+            }
+            const thisBindings: AnalyzerThisBinding[] = record.thisBindings.map(binding =>
+                Object.freeze({
+                    sourceValue: binding.sourceValue,
+                    targetValue: binding.targetValue,
+                    source: this.locationOfPagNode(binding.sourceNode),
+                    target: this.locationOfPagNode(binding.targetNode),
+                }),
+            );
+            const argumentBindings: AnalyzerArgumentParameterBinding[] =
+                record.argumentBindings.map(binding => Object.freeze({
+                    argumentIndex: binding.argumentIndex,
+                    parameterIndex: binding.parameterIndex,
+                    arrayElementIndex: binding.arrayElementIndex,
+                    sourceValue: binding.sourceValue,
+                    targetValue: binding.targetValue,
+                    source: this.locationOfPagNode(binding.sourceNode),
+                    target: this.locationOfPagNode(binding.targetNode),
+                }));
+            const argumentValueBindings: AnalyzerArgumentParameterValueBinding[] =
+                record.argumentValueBindings.map(binding => Object.freeze({
+                    argumentIndex: binding.argumentIndex,
+                    parameterIndex: binding.parameterIndex,
+                    sourceValue: binding.sourceValue,
+                    targetValue: binding.targetValue,
+                    parameterAssignment: binding.parameterAssignment,
+                    parameterLocal: binding.parameterLocal,
+                }));
+            const returnBindings: AnalyzerReturnResultBinding[] =
+                record.returnBindings.map(binding => Object.freeze({
+                    returnStatement: binding.returnStatement,
+                    returnValue: binding.returnValue,
+                    resultValue: binding.resultValue,
+                    sourceValue: binding.sourceValue,
+                    targetValue: binding.targetValue,
+                    source: this.locationOfPagNode(binding.sourceNode),
+                    target: this.locationOfPagNode(binding.targetNode),
+                }));
+            const fact: CallBindingFact = Object.freeze({
+                callsite: record.callsite,
+                occurrence,
+                caller: record.caller,
+                callee: record.callee,
+                callerContext: this.pointerContextRefFor(
+                    record.callerContext,
+                    contextCache,
+                    pointerContextRefs,
+                ),
+                calleeContext: this.pointerContextRefFor(
+                    record.calleeContext,
+                    contextCache,
+                    pointerContextRefs,
+                ),
+                thisBindings: Object.freeze(thisBindings),
+                argumentBindings: Object.freeze(argumentBindings),
+                argumentValueBindings: Object.freeze(argumentValueBindings),
+                returnBindings: Object.freeze(returnBindings),
+            });
+            const existing = this.callBindingsByStatement.get(record.callsite.callStmt) ?? [];
+            this.callBindingsByStatement.set(
+                record.callsite.callStmt,
+                Object.freeze([...existing, fact]),
+            );
+            this.callBindingFacts.add(fact);
+        }
+    }
+
+    private pointerContextRefFor(
+        contextId: number,
+        contextCache: ContextCache,
+        pointerContextRefs: Map<Context, AnalyzerContextRef>,
+    ): AnalyzerContextRef {
+        const context = contextCache.getContext(contextId);
+        const reference = context ? pointerContextRefs.get(context) : undefined;
+        if (!reference) {
+            throw new Error('call binding context is not owned by this PointerAnalysis');
+        }
+        return reference;
+    }
+
+    private publishCallableTargets(
+        records: readonly PagCallableTargetRecord[],
+        pointsTo: DiffPTData<NodeID, NodeID, IPtsCollection<NodeID>>,
+    ): void {
+        const targetByObject = new Map<PagFuncNode, PagCallableTargetRecord>();
+        for (const record of records) {
+            targetByObject.set(record.functionObject, record);
+        }
+        for (const value of this.pag.getValuesWithNodes()) {
+            const facts: CallableTargetFact[] = [];
+            for (const location of this.locationsOf(value)) {
+                if (location.kind !== 'pag') continue;
+                const targetObjects = new Set<PagFuncNode>();
+                if (location.node instanceof PagFuncNode && targetByObject.has(location.node)) {
+                    targetObjects.add(location.node);
+                }
+                for (const collection of [
+                    pointsTo.getPropaPts(location.node.getID()),
+                    pointsTo.getDiffPts(location.node.getID()),
+                ]) {
+                    if (!collection) continue;
+                    for (const targetId of collection) {
+                        const targetNode = this.pag.hasNode(targetId)
+                            ? this.pag.getNode(targetId)
+                            : undefined;
+                        if (targetNode instanceof PagFuncNode && targetByObject.has(targetNode)) {
+                            targetObjects.add(targetNode);
+                        }
+                    }
+                }
+                for (const functionObject of targetObjects) {
+                    const record = targetByObject.get(functionObject)!;
+                    const functionObjectLocation = this.locationOfPagNode(functionObject);
+                    const fact: CallableTargetFact = Object.freeze({
+                        callableValue: value,
+                        callableLocation: location,
+                        functionObject,
+                        functionObjectLocation,
+                        method: record.method,
+                        context: functionObjectLocation.context,
+                    });
+                    if (!facts.some(existing =>
+                        existing.callableLocation === fact.callableLocation
+                        && existing.functionObject === fact.functionObject,
+                    )) {
+                        facts.push(fact);
+                        this.callableTargetFacts.add(fact);
+                    }
+                }
+            }
+            if (facts.length > 0) {
+                this.callableTargetsByValue.set(value, Object.freeze(facts));
+            }
+        }
+    }
+
+    private publishClosureBindings(
+        records: readonly PagClosureBindingRecord[],
+        valueRecords: readonly PagClosureValueBindingRecord[],
+        contextCache: ContextCache,
+        pointerContextRefs: Map<Context, AnalyzerContextRef>,
+    ): void {
+        for (const record of records) {
+            if (!this.program.ownsMethod(record.executionUnit)) {
+                throw new Error('closure binding execution unit is outside this snapshot');
+            }
+            const fact: ClosureBindingFact = Object.freeze({
+                capturedValue: record.capturedValue,
+                capturedField: record.capturedField,
+                executionUnit: record.executionUnit,
+                source: this.locationOfPagNode(record.sourceNode),
+                target: this.locationOfPagNode(record.targetNode),
+            });
+            this.addClosureBindingFact(fact);
+        }
+        for (const record of valueRecords) {
+            if (!this.program.ownsMethod(record.executionUnit)
+                || !this.program.ownsStatement(record.statement)) {
+                throw new Error('primitive closure binding is outside this snapshot');
+            }
+            const sourceStatement = record.capturedValue instanceof Local
+                ? record.capturedValue.getDeclaringStmt()
+                : null;
+            if (!sourceStatement || !this.program.ownsStatement(sourceStatement)) {
+                // Without an Analyzer-owned definition statement there is no exact
+                // source location to publish. Fail closed by omitting this primitive
+                // closure fact instead of fabricating a source endpoint.
+                continue;
+            }
+            const sourceContext = this.pointerContextRefFor(
+                record.sourceContext,
+                contextCache,
+                pointerContextRefs,
+            );
+            const targetContext = this.pointerContextRefFor(
+                record.targetContext,
+                contextCache,
+                pointerContextRefs,
+            );
+            this.addClosureBindingFact(Object.freeze({
+                capturedValue: record.capturedValue,
+                capturedField: record.capturedField,
+                executionUnit: record.executionUnit,
+                source: this.valueFlowLocation(
+                    this.dvfg.getOrNewValueNode(
+                        sourceStatement,
+                        record.capturedValue,
+                        'definition',
+                    ),
+                    sourceContext,
+                ),
+                target: this.valueFlowLocation(
+                    this.dvfg.getOrNewValueNode(
+                        record.statement,
+                        record.targetValue,
+                        'definition',
+                    ),
+                    targetContext,
+                ),
+            }));
+        }
+    }
+
+    private addClosureBindingFact(fact: ClosureBindingFact): void {
+        const existing = this.closureBindingsByValue.get(fact.capturedValue) ?? [];
+        if (existing.some(candidate =>
+            candidate.capturedField === fact.capturedField
+            && candidate.executionUnit === fact.executionUnit
+            && candidate.source === fact.source
+            && candidate.target === fact.target,
+        )) {
+            return;
+        }
+        this.closureBindingsByValue.set(
+            fact.capturedValue,
+            Object.freeze([...existing, fact]),
+        );
+        this.closureBindingFacts.add(fact);
+    }
+
+    private publishFieldAccesses(
+        records: readonly RealizedPagFieldAccessRecord[],
+        pointsTo: DiffPTData<NodeID, NodeID, IPtsCollection<NodeID>>,
+        contextCache: ContextCache,
+        pointerContextRefs: Map<Context, AnalyzerContextRef>,
+    ): void {
+        for (const record of records) {
+            const site = this.fieldSiteFor(record.event);
+            const selector = this.fieldSelectorFor(
+                record.event.fieldRef,
+                record.event.stmt,
+                record.baseObject,
+                record.storage,
+            );
+            const baseValueLocation = this.locationOfPagNode(record.baseValueNode);
+            const baseObjectLocation = this.locationOfPagNode(record.baseObject);
+            const storageLocation = this.locationOfPagNode(record.storage);
+            const valueLocation = this.fieldAccessValueLocation(
+                record,
+                contextCache,
+                pointerContextRefs,
+            );
+            const common = {
+                site,
+                baseValue: record.event.fieldRef.getBase(),
+                baseObject: record.baseObject,
+                storage: record.storage,
+                selector,
+                baseValueLocation,
+                baseObjectLocation,
+                storageLocation,
+            };
+            const fact: FieldStoreFact | FieldLoadFact = record.event.kind === 'store'
+                ? Object.freeze({
+                    ...common,
+                    kind: 'store',
+                    value: record.event.value,
+                    source: valueLocation,
+                    target: storageLocation,
+                })
+                : Object.freeze({
+                    ...common,
+                    kind: 'load',
+                    value: record.event.value,
+                    source: storageLocation,
+                    target: valueLocation,
+                });
+            this.addFieldAccessFact(fact);
+        }
+
+        for (const event of this.pag.getFieldAccessEvents()) {
+            if (event.kind !== 'delete') continue;
+            const site = this.fieldSiteFor(event);
+            const selector = this.fieldSelectorFor(event.fieldRef, event.stmt);
+            const seenStorage = new Set<PagInstanceFieldNode>();
+            for (const baseLocation of this.locationsOf(event.fieldRef.getBase())) {
+                if (baseLocation.kind !== 'pag') continue;
+                for (const baseObject of this.pointsToObjects(baseLocation.node, pointsTo)) {
+                    const storage = this.pag.getExistingFieldStorage(
+                        baseObject,
+                        event.fieldRef,
+                        event.stmt,
+                    );
+                    if (!storage || seenStorage.has(storage)) continue;
+                    seenStorage.add(storage);
+                    const fact: FieldDeleteFact = Object.freeze({
+                        kind: 'delete',
+                        site,
+                        baseValue: event.fieldRef.getBase(),
+                        baseObject,
+                        storage,
+                        selector,
+                        baseValueLocation: baseLocation,
+                        baseObjectLocation: this.locationOfPagNode(baseObject),
+                        storageLocation: this.locationOfPagNode(storage),
+                    });
+                    this.addFieldAccessFact(fact);
+                }
+            }
+        }
+    }
+
+    private fieldAccessValueLocation(
+        record: RealizedPagFieldAccessRecord,
+        contextCache: ContextCache,
+        pointerContextRefs: Map<Context, AnalyzerContextRef>,
+    ): AnalyzerLocationRef {
+        const role = record.event.kind === 'store' ? 'use' : 'definition';
+        const context = this.pointerContextRefFor(
+            record.valueContext,
+            contextCache,
+            pointerContextRefs,
+        );
+        const occurrenceLocations: AnalyzerValueFlowLocationRef[] = [];
+        for (const node of this.dvfg.getValueNodes(record.event.value)) {
+            if (node.getStmt() !== record.event.stmt || node.getRole() !== role) continue;
+            const location = this.valueFlowLocations.get(node)?.get(context);
+            if (location && !occurrenceLocations.includes(location)) {
+                occurrenceLocations.push(location);
+            }
+        }
+        if (occurrenceLocations.length > 1) {
+            throw new Error('field access value has multiple exact value-flow occurrences in one Analyzer context');
+        }
+        if (occurrenceLocations.length === 1) {
+            return occurrenceLocations[0];
+        }
+        if (record.valueNode) {
+            return this.locationOfPagNode(record.valueNode);
+        }
+        const node = this.dvfg.getOrNewValueNode(
+            record.event.stmt,
+            record.event.value,
+            role,
+        );
+        return this.valueFlowLocation(node, context);
+    }
+
+    private addFieldAccessFact(fact: FieldAccessFact): void {
+        const existing = this.fieldAccessesByStatement.get(fact.site.statement) ?? [];
+        this.fieldAccessesByStatement.set(
+            fact.site.statement,
+            Object.freeze([...existing, fact]),
+        );
+        this.fieldAccessFacts.add(fact);
+    }
+
+    private fieldSiteFor(event: PagFieldAccessEvent): AnalyzerFieldSiteRef {
+        const method = event.stmt.getCfg()?.getDeclaringMethod();
+        if (!method || !this.program.ownsMethod(method)) {
+            throw new Error('field access event is outside this snapshot');
+        }
+        const site = this.program.fieldSites(method).find(candidate =>
+            candidate.kind === event.kind
+            && candidate.statement === event.stmt
+            && candidate.fieldRef === event.fieldRef,
+        );
+        if (!site) {
+            throw new Error('field access event has no exact program-model site');
+        }
+        return site;
+    }
+
+    private fieldSelectorFor(
+        fieldRef: ArkInstanceFieldRef | ArkArrayRef,
+        statement: ArkAssignStmt,
+        baseObject?: PagNode,
+        storage?: PagInstanceFieldNode,
+    ): AnalyzerFieldSelector {
+        if (fieldRef instanceof ArkInstanceFieldRef) {
+            const containerSelector = baseObject instanceof PagNewContainerExprNode
+                && storage
+                ? baseObject.selectorOfElementNode(storage.getID())
+                : undefined;
+            if (containerSelector?.kind === 'array-index') {
+                return Object.freeze({
+                    kind: 'array-index',
+                    access: fieldRef,
+                    index: containerSelector.index,
+                });
+            }
+            if (containerSelector?.kind === 'array-wildcard') {
+                return Object.freeze({
+                    kind: 'array-wildcard',
+                    access: fieldRef,
+                });
+            }
+            return Object.freeze({
+                kind: 'field',
+                access: fieldRef,
+            });
+        }
+        const index = resolveArrayElementIndex({
+            arrayRef: fieldRef,
+            stmt: statement,
+        });
+        return index === undefined
+            ? Object.freeze({
+                kind: 'array-wildcard',
+                access: fieldRef,
+            })
+            : Object.freeze({
+                kind: 'array-index',
+                access: fieldRef,
+                index,
+            });
+    }
+
+    private pointsToObjects(
+        location: PagNode,
+        pointsTo: DiffPTData<NodeID, NodeID, IPtsCollection<NodeID>>,
+    ): readonly PagNode[] {
+        const objects = new Set<PagNode>();
+        for (const collection of [
+            pointsTo.getPropaPts(location.getID()),
+            pointsTo.getDiffPts(location.getID()),
+        ]) {
+            if (!collection) continue;
+            for (const objectId of collection) {
+                const object = this.pag.hasNode(objectId)
+                    ? this.pag.getNode(objectId)
+                    : undefined;
+                if (object instanceof PagNode) objects.add(object);
+            }
+        }
+        return Object.freeze([...objects]);
+    }
+
+    private publishValueFlows(
+        methodContextRecords: readonly PagMethodContextRecord[],
+        callBindingRecords: readonly PagCallBindingRecord[],
+        semanticValueFlowRecords: readonly PagSemanticValueFlowRecord[],
+        contextCache: ContextCache,
+        pointerContextRefs: Map<Context, AnalyzerContextRef>,
+    ): void {
+        const contextsByMethod = new Map<ArkMethod, AnalyzerContextRef[]>();
+        const builder = new DVFGBuilder(this.dvfg, this.program.scene);
+        for (const record of methodContextRecords) {
+            if (!this.program.ownsMethod(record.method)) {
+                throw new Error('method context is outside this snapshot');
+            }
+            const context = this.pointerContextRefFor(
+                record.context,
+                contextCache,
+                pointerContextRefs,
+            );
+            const contexts = contextsByMethod.get(record.method) ?? [];
+            if (!contexts.includes(context)) contexts.push(context);
+            contextsByMethod.set(record.method, contexts);
+            if (record.method.getCfg()) {
+                builder.buildForSingleMethod(record.method);
+            }
+        }
+        const valueFlowDomain = this.classifyValueFlowDomain(
+            callBindingRecords,
+            semanticValueFlowRecords,
+        );
+
+        for (const edge of this.dvfg.getValueFlowEdges()) {
+            const kind = this.valueFlowKind(edge);
+            if (!kind) continue;
+            const ordinaryOperation = kind === 'ordinary-transfer'
+                ? this.requireOrdinaryValueFlowOperation(edge)
+                : undefined;
+            const definition = edge.getDefinition();
+            const use = edge.getUse();
+            const sourceValue = edge.getSourceValue();
+            const targetValue = edge.getTargetValue();
+            const sourceNode = edge.getSrcNode();
+            const targetNode = edge.getDstNode();
+            if (!definition
+                || !use
+                || !sourceValue
+                || !targetValue
+                || !(sourceNode instanceof DVFGNode)
+                || !(targetNode instanceof DVFGNode)) {
+                throw new Error('DVFG value-flow edge lacks exact relation objects');
+            }
+            if (!valueFlowDomain.has(sourceValue)
+                && !valueFlowDomain.has(targetValue)
+                && ordinaryOperation !== 'await') {
+                continue;
+            }
+            const sourceMethod = definition.getCfg()?.getDeclaringMethod();
+            const targetMethod = targetNode.getStmt().getCfg()?.getDeclaringMethod();
+            if (!sourceMethod
+                || !targetMethod
+                || sourceMethod !== targetMethod
+                || !this.program.ownsMethod(sourceMethod)) {
+                throw new Error('intra-procedural DVFG edge crosses method ownership');
+            }
+            for (const context of contextsByMethod.get(sourceMethod) ?? []) {
+                const common = {
+                    definition,
+                    use,
+                    sourceValue,
+                    targetValue,
+                    sourceMethod,
+                    targetMethod,
+                    source: this.valueFlowLocation(sourceNode, context),
+                    target: this.valueFlowLocation(targetNode, context),
+                    sourceContext: context,
+                    targetContext: context,
+                };
+                this.addValueFlowFact(kind === 'ordinary-transfer'
+                    ? Object.freeze({
+                        ...common,
+                        kind: 'ordinary-transfer',
+                        operation: ordinaryOperation!,
+                    })
+                    : Object.freeze({
+                        ...common,
+                        kind,
+                    }) as ValueFlowFact);
+            }
+        }
+
+        for (const call of callBindingRecords) {
+            const callerContext = this.pointerContextRefFor(
+                call.callerContext,
+                contextCache,
+                pointerContextRefs,
+            );
+            const calleeContext = this.pointerContextRefFor(
+                call.calleeContext,
+                contextCache,
+                pointerContextRefs,
+            );
+            for (const argument of call.argumentValueBindings) {
+                if (!(argument.sourceValue instanceof Local)) continue;
+                const parameterAssignment = call.callee.getCfg()?.getStmts().find(statement =>
+                    statement instanceof ArkAssignStmt
+                    && statement.getRightOp() === argument.targetValue
+                    && statement.getLeftOp() instanceof Local,
+                );
+                if (!(parameterAssignment instanceof ArkAssignStmt)
+                    || !(parameterAssignment.getLeftOp() instanceof Local)) {
+                    continue;
+                }
+                const targetValue = parameterAssignment.getLeftOp();
+                if (!valueFlowDomain.has(argument.sourceValue)
+                    && !valueFlowDomain.has(targetValue)) {
+                    continue;
+                }
+                const targetNode = this.dvfg.getOrNewValueNode(
+                    parameterAssignment,
+                    targetValue,
+                    'definition',
+                );
+                for (const reaching of this.reachingDefinitionsAt(
+                    call.callsite.callStmt,
+                    argument.sourceValue,
+                )) {
+                    const definition = reaching.getDefinition();
+                    const sourceNode = reaching.getSrcNode();
+                    if (!definition || !(sourceNode instanceof DVFGNode)) continue;
+                    this.addValueFlowFact(Object.freeze({
+                        kind: 'call-argument',
+                        definition,
+                        use: call.callsite.callStmt,
+                        sourceValue: argument.sourceValue,
+                        targetValue,
+                        sourceMethod: call.caller,
+                        targetMethod: call.callee,
+                        source: this.valueFlowLocation(sourceNode, callerContext),
+                        target: this.valueFlowLocation(targetNode, calleeContext),
+                        sourceContext: callerContext,
+                        targetContext: calleeContext,
+                    }));
+                }
+            }
+            for (const returned of call.returnValueBindings) {
+                if (!(returned.returnValue instanceof Local)
+                    || !(returned.resultValue instanceof Local)) {
+                    continue;
+                }
+                if (!valueFlowDomain.has(returned.returnValue)
+                    && !valueFlowDomain.has(returned.resultValue)) {
+                    continue;
+                }
+                const targetNode = this.dvfg.getOrNewValueNode(
+                    call.callsite.callStmt,
+                    returned.resultValue,
+                    'definition',
+                );
+                for (const reaching of this.reachingDefinitionsAt(
+                    returned.returnStatement,
+                    returned.returnValue,
+                )) {
+                    const definition = reaching.getDefinition();
+                    const sourceNode = reaching.getSrcNode();
+                    if (!definition || !(sourceNode instanceof DVFGNode)) continue;
+                    this.addValueFlowFact(Object.freeze({
+                        kind: 'call-return',
+                        definition,
+                        use: returned.returnStatement,
+                        sourceValue: returned.returnValue,
+                        targetValue: returned.resultValue,
+                        sourceMethod: call.callee,
+                        targetMethod: call.caller,
+                        source: this.valueFlowLocation(sourceNode, calleeContext),
+                        target: this.valueFlowLocation(targetNode, callerContext),
+                        sourceContext: calleeContext,
+                        targetContext: callerContext,
+                    }));
+                }
+            }
+        }
+
+        for (const record of semanticValueFlowRecords) {
+            if (!this.program.ownsMethod(record.sourceMethod)
+                || !this.program.ownsMethod(record.targetMethod)
+                || !this.program.ownsStatement(record.sourceStatement)
+                || !this.program.ownsStatement(record.targetStatement)) {
+                throw new Error('semantic value-flow record is outside this snapshot');
+            }
+            const sourceContext = this.pointerContextRefFor(
+                record.sourceContext,
+                contextCache,
+                pointerContextRefs,
+            );
+            const targetContext = this.pointerContextRefFor(
+                record.targetContext,
+                contextCache,
+                pointerContextRefs,
+            );
+            const sourceNode = this.dvfg.getOrNewValueNode(
+                record.sourceStatement,
+                record.sourceValue,
+                'use',
+            );
+            const targetNode = this.dvfg.getOrNewValueNode(
+                record.targetStatement,
+                record.targetValue,
+                'definition',
+            );
+            this.addValueFlowFact(Object.freeze({
+                kind: 'semantic-summary',
+                definition: record.sourceStatement,
+                use: record.targetStatement,
+                sourceValue: record.sourceValue,
+                targetValue: record.targetValue,
+                sourceMethod: record.sourceMethod,
+                targetMethod: record.targetMethod,
+                source: this.valueFlowLocation(sourceNode, sourceContext),
+                target: this.valueFlowLocation(targetNode, targetContext),
