+import type { Stmt } from "../base/Stmt";
+import type { BasicBlock } from "../graph/BasicBlock";
+import type { Cfg } from "../graph/Cfg";
+import type { ArkMethod } from "./ArkMethod";
+
+export class AnalyzerControlFlowFacts {
+    readonly statements: readonly Stmt[];
+    readonly blocks: readonly BasicBlock[];
+
+    private readonly blockByStatement = new Map<Stmt, BasicBlock>();
+    private readonly statementOrder = new Map<Stmt, number>();
+    private readonly statementOrderInBlock = new Map<Stmt, number>();
+    private readonly normalSuccessors = new Map<BasicBlock, readonly BasicBlock[]>();
+    private readonly exceptionalSuccessors = new Map<BasicBlock, readonly BasicBlock[]>();
+    private readonly allSuccessors = new Map<BasicBlock, readonly BasicBlock[]>();
+    private readonly reachableBlocks = new Map<BasicBlock, ReadonlySet<BasicBlock>>();
+    private readonly dominators = new Map<BasicBlock, ReadonlySet<BasicBlock>>();
+    private readonly ownedStatements = new Set<Stmt>();
+    private readonly ownedBlocks = new Set<BasicBlock>();
+
+    constructor(
+        readonly method: ArkMethod,
+        readonly cfg: Cfg,
+    ) {
+        if (method.getCfg() !== cfg || cfg.getDeclaringMethod() !== method) {
+            throw new Error("control-flow facts require the method's exact CFG");
+        }
+
+        this.statements = Object.freeze([...cfg.getStmts()]);
+        this.blocks = Object.freeze([...cfg.getBlocks()]);
+        const cfgBlockByStatement = cfg.getStmtToBlock();
+        for (const block of this.blocks) {
+            this.ownedBlocks.add(block);
+            const statements = [...block.getStmts()];
+            statements.forEach((statement, index) => {
+                if (cfgBlockByStatement.get(statement) !== block) {
+                    throw new Error("CFG statement-to-block relation is inconsistent");
+                }
+                this.ownedStatements.add(statement);
+                this.blockByStatement.set(statement, block);
+                this.statementOrderInBlock.set(statement, index);
+            });
+            const normal = Object.freeze([...block.getSuccessors()]);
+            const exceptional = Object.freeze([
+                ...(block.getExceptionalSuccessorBlocks() ?? []),
+            ]);
+            this.normalSuccessors.set(block, normal);
+            this.exceptionalSuccessors.set(block, exceptional);
+            this.allSuccessors.set(
+                block,
+                Object.freeze([...new Set([...normal, ...exceptional])]),
+            );
+        }
+        this.statements.forEach((statement, index) => {
+            if (!this.ownedStatements.has(statement)) {
+                throw new Error("CFG statement order contains an unowned statement");
+            }
+            this.statementOrder.set(statement, index);
+        });
+        if (this.statementOrder.size !== this.ownedStatements.size) {
+            throw new Error("CFG statement order is incomplete");
+        }
+
+        this.publishReachability();
+        this.publishDominance();
+        Object.freeze(this);
+    }
+
+    blockOf(statement: Stmt): BasicBlock | undefined {
+        return this.blockByStatement.get(statement);
+    }
+
+    statementOrderOf(statement: Stmt): number {
+        const order = this.statementOrder.get(statement);
+        if (order === undefined) {
+            throw new Error("statement is not owned by these control-flow facts");
+        }
+        return order;
+    }
+
+    normalSuccessorsOf(block: BasicBlock): readonly BasicBlock[] {
+        this.assertOwnedBlock(block);
+        return this.normalSuccessors.get(block)!;
+    }
+
+    exceptionalSuccessorsOf(block: BasicBlock): readonly BasicBlock[] {
+        this.assertOwnedBlock(block);
+        return this.exceptionalSuccessors.get(block)!;
+    }
+
+    successorsOf(block: BasicBlock): readonly BasicBlock[] {
+        this.assertOwnedBlock(block);
+        return this.allSuccessors.get(block)!;
+    }
+
+    dominates(dominator: BasicBlock, target: BasicBlock): boolean {
+        this.assertOwnedBlock(dominator);
+        this.assertOwnedBlock(target);
+        return this.dominators.get(target)?.has(dominator) ?? false;
+    }
+
+    reachable(source: BasicBlock, target: BasicBlock): boolean {
+        this.assertOwnedBlock(source);
+        this.assertOwnedBlock(target);
+        return this.reachableBlocks.get(source)?.has(target) ?? false;
+    }
+
+    isBeforeInBlock(first: Stmt, second: Stmt): boolean {
+        const block = this.blockByStatement.get(first);
+        if (!block || this.blockByStatement.get(second) !== block) return false;
+        return this.statementOrderInBlock.get(first)! < this.statementOrderInBlock.get(second)!;
+    }
+
+    statementsBefore(statement: Stmt): readonly Stmt[] {
+        const block = this.blockByStatement.get(statement);
+        const order = this.statementOrderInBlock.get(statement);
+        if (!block || order === undefined) {
+            throw new Error("statement is not owned by these control-flow facts");
+        }
+        return Object.freeze(block.getStmts().slice(0, order));
+    }
+
+    ownsStatement(statement: Stmt): boolean {
+        return this.ownedStatements.has(statement);
+    }
+
+    ownsBlock(block: BasicBlock): boolean {
+        return this.ownedBlocks.has(block);
+    }
+
+    private publishReachability(): void {
+        for (const source of this.blocks) {
+            const reached = new Set<BasicBlock>([source]);
+            const pending = [source];
+            while (pending.length > 0) {
+                const current = pending.shift()!;
+                for (const successor of this.allSuccessors.get(current) ?? []) {
+                    if (!this.ownedBlocks.has(successor)) {
+                        throw new Error("CFG successor is outside the declaring CFG");
+                    }
+                    if (reached.has(successor)) continue;
+                    reached.add(successor);
+                    pending.push(successor);
+                }
+            }
+            this.reachableBlocks.set(source, reached);
+        }
+    }
+
+    private publishDominance(): void {
+        const entry = this.cfg.getStartingBlock();
+        if (!entry || !this.ownedBlocks.has(entry)) {
+            throw new Error("CFG has no exact starting block");
+        }
+        const entryReachable = this.reachableBlocks.get(entry) ?? new Set<BasicBlock>();
+        const predecessors = new Map<BasicBlock, Set<BasicBlock>>();
+        for (const block of this.blocks) predecessors.set(block, new Set());
+        for (const block of this.blocks) {
+            for (const successor of this.allSuccessors.get(block) ?? []) {
+                predecessors.get(successor)?.add(block);
+            }
+        }
+
+        const mutable = new Map<BasicBlock, Set<BasicBlock>>();
+        for (const block of this.blocks) {
+            if (!entryReachable.has(block)) {
+                mutable.set(block, new Set());
+            } else if (block === entry) {
+                mutable.set(block, new Set([entry]));
+            } else {
+                mutable.set(block, new Set(entryReachable));
+            }
+        }
+
+        let changed = true;
+        while (changed) {
+            changed = false;
+            for (const block of this.blocks) {
+                if (block === entry || !entryReachable.has(block)) continue;
+                const reachablePredecessors = [...(predecessors.get(block) ?? [])]
+                    .filter(predecessor => entryReachable.has(predecessor));
+                const next = reachablePredecessors.length === 0
+                    ? new Set<BasicBlock>()
+                    : intersection(
+                        reachablePredecessors.map(predecessor => mutable.get(predecessor)!),
+                    );
+                next.add(block);
+                if (!setsEqual(next, mutable.get(block)!)) {
+                    mutable.set(block, next);
+                    changed = true;
+                }
+            }
+        }
+        for (const block of this.blocks) {
+            this.dominators.set(block, mutable.get(block)!);
+        }
+    }
+
+    private assertOwnedBlock(block: BasicBlock): void {
+        if (!this.ownedBlocks.has(block)) {
+            throw new Error("basic block is not owned by these control-flow facts");
+        }
+    }
+}
+
+function intersection(sets: readonly ReadonlySet<BasicBlock>[]): Set<BasicBlock> {
+    if (sets.length === 0) return new Set();
+    const result = new Set(sets[0]);
+    for (const candidate of result) {
+        if (sets.some(set => !set.has(candidate))) result.delete(candidate);
+    }
+    return result;
+}
+
+function setsEqual(
+    left: ReadonlySet<BasicBlock>,
+    right: ReadonlySet<BasicBlock>,
+): boolean {
+    if (left.size !== right.size) return false;
+    for (const value of left) if (!right.has(value)) return false;
+    return true;
+}

